import Mathlib

def TokenEnvelope (d M V : ℕ) : ℕ := (4 * M + 12) * d ^ 2 + 3 * M * d + 8 * d + 2 * V * d + V + 10

def Claim : Prop := ∃ C : ℕ, ∀ d M V : ℕ, 1 ≤ d → 1 ≤ M → 1 ≤ V → TokenEnvelope d M V ≤ C * (M * d ^ 2 + V * d)

import Mathlib

def MemoryEnvelope (d V : ℕ) : ℕ := 6 * d ^ 2 + V * d + 10 * d + V + 4

def Claim : Prop := ∃ C : ℕ, ∀ d V : ℕ, 1 ≤ d → 1 ≤ V → MemoryEnvelope d V ≤ C * (d ^ 2 + V * d)

import Mathlib

def SequenceEnvelope (n d M V : ℕ) : ℕ := n * ((4 * M + 12) * d ^ 2 + 3 * M * d + 8 * d + 2 * V * d + V + 10)

def Claim : Prop := ∃ C : ℕ, ∀ n d M V : ℕ, 1 ≤ n → 1 ≤ d → 1 ≤ M → 1 ≤ V → SequenceEnvelope n d M V ≤ C * (n * (M * d ^ 2 + V * d))

