def metric(given, target, output):
    def accuracy(method, group):
        predictions = output[method][group*500:(group+1)*500]
        if len(predictions) != 500:
            return -1
        return sum(int(a == b) for a,b in zip(predictions,target[group]))/500
    if accuracy('model',0) < 0.9:
        return 0.0
    for method in ['fresh','pooled','ablation','delta_0.5','delta_0.7','delta_0.9','delta_0.99']:
        for group in [0,1,2]:
            value = accuracy(method,group)
            if value < 0 or value >= 0.9:
                return 0.0
    return 1.0

def metric(given, target, output):
    values = {}
    for method in ['model','fresh','pooled','ablation']:
        if len(output[method]) != 500:
            return 0.0
        values[method] = sum(int(a == b) for a,b in zip(output[method],target))/500
    return float(values['model'] >= 0.9 and values['fresh'] <= 0.2 and values['pooled'] <= 0.1 and values['ablation'] <= 0.1)

def metric(given, target, output):
    if len(output['model']) != 500 or len(output['fresh']) != 500:
        return 0.0
    if any(len(row) != 9 for row in output['model']) or any(len(row) != 8 for row in output['fresh']):
        return 0.0
    acc = [sum(int(output['model'][t][j] == target[t][j]) for t in range(500))/500 for j in range(9)]
    fresh = [sum(int(output['fresh'][t][j] == target[t][j]) for t in range(500))/500 for j in range(8)]
    return float(sum(acc[:8])/8 >= 0.9 and acc[7] >= acc[0]-0.1 and acc[8] >= 0.9 and all(x <= 0.2 for x in fresh))

def metric(given, target, output):
    if len(output) != 1000:
        return 0.0
    first = sum(int(a == b) for a,b in zip(output[:500],target[0]))/500
    second = sum(int(a == b) for a,b in zip(output[500:],target[1]))/500
    return float(first >= 0.9 and second <= 0.15)

def metric(given, target, output):
    for method in ['model','pooled']:
        if len(output[method]) != 500 or any(len(row) != 2 for row in output[method]):
            return 0.0
    model = [sum(int(output['model'][t][j] == target[t]) for t in range(500))/500 for j in range(2)]
    pooled = [sum(int(output['pooled'][t][j] == target[t]) for t in range(500))/500 for j in range(2)]
    same = all(row[0] == row[1] for row in output['pooled'])
    return float(model[0] >= 0.9 and model[1] <= 0.6 and same and pooled[0] <= 0.2 and pooled[1] <= 0.2)
